from __future__ import annotations

PAGE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#f6f7fb">
<title>LeadHunter · Overview</title>
<style>
:root{--bg:#f6f7fb;--card:#fff;--text:#151923;--muted:#707887;--line:#e5e8ef;--accent:#655cf5;--accent-soft:#efedff;--green:#16845d;--green-soft:#e8f7ef;--orange:#a86a00;--orange-soft:#fff3dc;--shadow:0 12px 36px rgba(24,30,50,.07);--radius:18px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Inter,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}button{font:inherit;cursor:pointer}.shell{max-width:1280px;margin:auto;padding:20px 24px 48px}.top{height:58px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px}.logo{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,#e9e6ff,#dff7f5);font-size:20px}.brand b{display:block;font-size:17px}.brand small{display:block;color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.version{font-size:10px;color:var(--muted)}.hero{padding:52px 0 25px;display:flex;align-items:flex-end;justify-content:space-between;gap:28px}.eyebrow{color:var(--accent);font-size:10px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}.hero h1{margin:7px 0 10px;font-size:clamp(38px,5vw,62px);line-height:.94;letter-spacing:-.06em}.hero p{margin:0;color:var(--muted);max-width:650px}.btn{border:1px solid var(--line);background:var(--card);color:var(--text);border-radius:11px;padding:10px 14px;font-weight:850;transition:.18s}.btn:hover{transform:translateY(-1px);box-shadow:0 7px 20px rgba(24,30,50,.08)}.primary{background:var(--accent);border-color:var(--accent);color:#fff;box-shadow:0 8px 22px rgba(101,92,245,.22)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric,.panel{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.metric{padding:18px;min-height:118px}.metric small{display:block;color:var(--muted);font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.13em}.metric strong{display:block;font-size:31px;line-height:1.05;margin-top:12px;letter-spacing:-.04em}.metric span{display:block;color:var(--muted);font-size:10px;margin-top:5px}.grid{display:grid;grid-template-columns:1.15fr .85fr;gap:12px;margin-top:12px}.panel{padding:18px}.panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:14px}.panel-head h2{margin:0;font-size:16px}.panel-head p{margin:3px 0 0;color:var(--muted);font-size:11px}.recent{display:grid;gap:8px}.lead{border:1px solid var(--line);border-radius:14px;padding:13px 14px;transition:.18s}.lead:hover{transform:translateY(-1px);border-color:#cbc7ff}.lead-main{display:flex;justify-content:space-between;align-items:center;gap:15px}.lead-name{font-weight:900;font-size:13px}.lead-sub{color:var(--muted);font-size:10px;margin-top:3px}.score{min-width:44px;text-align:center;padding:7px 8px;border-radius:10px;background:var(--accent-soft);color:var(--accent);font-weight:950}.lead-foot{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.tag{font-size:9px;font-weight:800;color:var(--muted);border:1px solid var(--line);border-radius:8px;padding:4px 7px}.tag.good{color:var(--green);background:var(--green-soft);border-color:#d4efdf}.tag.warn{color:var(--orange);background:var(--orange-soft);border-color:#f3e1b9}.quick{border:1px solid var(--line);background:linear-gradient(135deg,#faf9ff,#f7ffff);border-radius:15px;padding:17px}.quick-title{font-size:12px;font-weight:900}.quick p{margin:4px 0 15px;color:var(--muted);font-size:11px}.quick .btn{width:100%}.empty{padding:28px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:13px;background:#fafbfc;font-size:11px}.loading{animation:pulse 1.2s infinite}@keyframes pulse{50%{opacity:.45}}.status{font-size:10px;color:var(--muted);margin-top:9px}.toast{position:fixed;right:20px;bottom:20px;background:#171923;color:#fff;padding:10px 13px;border-radius:11px;font-size:11px;opacity:0;transform:translateY(8px);transition:.2s;z-index:20}.toast.show{opacity:1;transform:none}@media(max-width:850px){.shell{padding:12px 12px 35px}.version{display:none}.hero{padding:34px 0 20px;align-items:flex-start;flex-direction:column}.hero h1{font-size:43px}.hero>.btn{width:100%}.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:450px){.shell{padding-left:8px;padding-right:8px}.metrics{gap:7px}.metric{padding:13px;min-height:100px}.metric strong{font-size:25px}.hero h1{font-size:38px}}
</style>
</head>
<body><div class="shell">
<header class="top"><div class="brand"><div class="logo">🎯</div><div><b>LeadHunter</b><small>Lead generation workspace</small></div></div><span class="version">Overview · v3.1.0</span></header>
<main>
<section class="hero"><div><div class="eyebrow">Overview</div><h1>Find better leads.<br>Work them simply.</h1><p>Your lead-generation workspace for discovering businesses, understanding opportunities, and keeping your lead list organized.</p></div><button class="btn primary" onclick="goFind()">🔎 Find new leads</button></section>
<section class="metrics"><div class="metric"><small>Total leads</small><strong id="total">—</strong><span>Saved businesses</span></div><div class="metric"><small>New</small><strong id="new">—</strong><span>Ready to review</span></div><div class="metric"><small>Priority</small><strong id="hot">—</strong><span>Highest opportunity</span></div><div class="metric"><small>Contacted</small><strong id="contacted">—</strong><span>Manually contacted</span></div></section>
<div class="grid"><section class="panel"><div class="panel-head"><div><h2>Recent leads</h2><p>Your latest saved businesses.</p></div><button class="btn" onclick="goLeads()">View all →</button></div><div id="recent" class="recent"><div class="empty loading">Loading your leads…</div></div></section>
<section class="panel"><div class="panel-head"><div><h2>Start a search</h2><p>Find businesses by type and location.</p></div></div><div class="quick"><div class="quick-title">🔎 Build your next lead list</div><p>Choose the business type and city on the search page, then let LeadHunter find and organize the results.</p><button class="btn primary" onclick="goFind()">Start finding leads</button></div><div class="status" id="searchStatus">Loading workspace data…</div></section></div>
</main></div><div class="toast" id="toast"></div>
<script>
const $=id=>document.getElementById(id);const esc=x=>{const d=document.createElement('div');d.textContent=x??'';return d.innerHTML};async function api(url){const r=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json'}});let d=null;try{d=await r.json()}catch(e){}if(!r.ok)throw Error(d?.detail||`Request failed (${r.status})`);return d}function toast(t){const e=$('toast');e.textContent=t;e.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>e.classList.remove('show'),2200)}function goFind(){location.hash='find';toast('Find Leads page is next in the rebuild.')}function goLeads(){location.hash='leads';toast('Leads page is next in the rebuild.')}function leadCard(l){const g=(l.research||{}).google||{};const score=Number(l.score||0);const priority=l.priority||'—';return `<article class="lead"><div class="lead-main"><div><div class="lead-name">${esc(l.name||'Unnamed business')}</div><div class="lead-sub">${esc(l.industry||'Business')} · ${esc(l.city||'—')}</div></div><div class="score">${score}</div></div><div class="lead-foot"><span class="tag ${priority==='HOT'?'warn':''}">🔥 ${esc(priority)}</span><span class="tag">${esc(l.status||'NEW')}</span>${l.website?'<span class="tag good">🌐 Website</span>':''}${g.rating?`<span class="tag">⭐ ${esc(g.rating)}</span>`:''}</div></article>`}async function load(){try{const [a,b]=await Promise.all([api('/dashboard/api/leads?limit=10&offset=0'),api('/dashboard/api/analytics')]);const leads=a.leads||[];const t=b.totals||{};$('total').textContent=t.leads??0;$('hot').textContent=t.hot??0;$('new').textContent=leads.filter(x=>(x.status||'NEW')==='NEW').length;$('contacted').textContent=t.contacted??0;$('recent').innerHTML=leads.length?leads.slice(0,5).map(leadCard).join(''):'<div class="empty">No leads yet. Start your first search.</div>';$('searchStatus').textContent='Workspace data is up to date.'}catch(e){$('recent').innerHTML=`<div class="empty">Couldn’t load workspace data.<br><button class="btn" onclick="load()" style="margin-top:10px">Retry</button></div>`;$('searchStatus').textContent=e.message}}load();
</script></body></html>'''
